"""공통 조명 확인 HTML. CPU Lambert 시안이며 Unity 렌더/실측이 아님."""
from pathlib import Path
import json,base64
HERE=Path(__file__).resolve().parent;ROOT=HERE.parents[2]
def data(p):return 'data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode()
def make(folder,filename,is_texture=False):
 info=json.loads((folder/'manifest.json').read_text(encoding='utf-8'));payload=[]
 for item in info:
  d=dict(item);d['colorUrl']=data(folder/item['albedo']);d['normalUrl']=data(folder/item['normal']);payload.append(d)
 title='3D 배경 도트 질감 · 노멀맵 9종' if is_texture else '캐릭터 노멀맵 견본 2종'
 options=''.join(f'<option value="{i}">{a["label"]}</option>' for i,a in enumerate(info))
 body='''<!doctype html><html lang="ko"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>__TITLE__</title><style>*{box-sizing:border-box}[hidden]{display:none!important}body{margin:0;background:#131e1a;color:#eee4d0;font:16px/1.6 'Malgun Gothic',sans-serif}main{max-width:1380px;padding:28px;margin:auto}h1,h2{font-family:'Batang',serif;color:#e5c98a;font-weight:400}h1{font-size:34px}p{max-width:1000px}.muted{color:#b7beab}.bar{display:flex;flex-wrap:wrap;align-items:center;gap:18px;background:#26372b;border:1px solid #788061;padding:20px}.bar label{display:flex;gap:8px;align-items:center}button,select{font:inherit;min-height:44px;background:#344a39;color:#eee5ce;border:1px solid #a79b6b;padding:6px 12px}button{cursor:pointer}button:disabled{opacity:.4}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #eacb75}input[type=range]{width:140px}.cards{display:grid;grid-template-columns:1fr 1fr 1fr;gap:18px;margin:24px 0}.card{border:1px solid #738069;padding:18px;background:#26352b}.card h2{font-size:20px;margin:0 0 12px}.frame{position:relative;background:repeating-conic-gradient(#354d3b 0 25%,#2d4133 0 50%) 0/24px 24px;min-height:390px;display:flex;align-items:center;justify-content:center;overflow:hidden}.frame.normal{background:#8080ff}.frame canvas{width:100%;height:100%;max-height:520px;object-fit:contain;image-rendering:pixelated}.meta{padding:14px 20px;background:#1f3024;border-left:3px solid #b9a16b;white-space:pre-line}.small{font-size:13px}.readout{display:flex;gap:24px;flex-wrap:wrap;color:#e8cb89}.note{border-top:1px solid #667158;padding-top:20px;margin-top:24px}a{color:#dfc184}body.texture .frame{min-height:0;aspect-ratio:1}.pills{display:flex;gap:12px;flex-wrap:wrap}.pill{border:1px solid #697a61;padding:8px 14px}button.active{background:#806a38}@media(max-width:850px){.cards{grid-template-columns:1fr}.frame canvas{max-width:384px}.frame{min-height:300px}.bar label{flex-wrap:wrap}main{padding:16px}}</style><main><p class="muted small">HUMAN LAST RAMPART · 사용자 견본 검토 · Game 미연결</p><h1>__TITLE__</h1><p>왼쪽은 색 그림, 가운데는 표면 방향, 오른쪽은 빛을 적용한 모습입니다. 광원 방향과 높이를 바꿔 굴곡을 비교하세요.</p><div class="bar"><label>대상 <select id="asset">__OPTIONS__</select></label><label id="rowControl">행 <select id="row"></select></label><div id="frameControl"><button id="prev">이전 칸</button> <button id="next">다음 칸</button> <button id="play">재생</button></div><label>빛 방향 <input id="azimuth" aria-label="빛 방향" type="range" min="-180" max="180" value="135"><output id="azValue">135°</output></label><label>빛 높이 <input id="elevation" aria-label="빛 높이" type="range" min="5" max="85" value="35"><output id="elValue">35°</output></label><label><input id="flat" type="checkbox">평면 노멀과 비교</label><label id="repeatControl" hidden>반복 <select id="repeat"><option value="1">1×1</option><option value="2" selected>2×2</option><option value="3">3×3</option></select></label></div><div class="readout"><p id="frameLabel"></p><p id="renderStatus" aria-live="polite">이미지 로드 중</p></div><div class="cards"><section class="card"><h2>색 그림</h2><div class="frame"><canvas id="color" aria-label="색 그림 미리보기"></canvas></div></section><section class="card"><h2>노멀맵 · 위쪽이 +Y</h2><div class="frame normal"><canvas id="normal" aria-label="노멀맵 미리보기"></canvas></div></section><section class="card"><h2>빛 적용 <span id="litMode">입체</span></h2><div class="frame"><canvas id="lit" aria-label="빛 적용 미리보기"></canvas></div></section></div><div class="meta" id="meta"></div><p id="textureNote" class="muted" hidden>2×2 반복에서 타일 경계를 확인하세요. AI 원안에서 뽑은 질감을 미러 반복 규격으로 출력했고, 노멀의 반사 방향도 함께 맞췄습니다. 모든 최종 파일은 1m당 32화소입니다.</p><div class="note"><p>이 화면은 단순 Lambert 조명 계산 시안입니다. 실제 Unity 재질·빌보드 좌표계·색 공간·그림자·톤매핑 결과와 다를 수 있습니다.</p><p class="muted">노멀은 RGB 선형 데이터, 색은 sRGB입니다. 빈 영역은 (128,128,255)로 내보내고 실제 투명도는 색 그림의 알파를 사용합니다. 노멀맵은 실루엣이나 모델 모양을 바꾸지 않습니다.</p><p class="muted">캐릭터 나머지 노멀맵은 견본 사용자 확인 뒤 제작합니다. 3D 모형·재질 연결·Unity 캡처는 Claude 담당입니다. AI 내부 표면 대응은 육안 검토가 필요합니다.</p></div></main><script>
const items=__DATA__,texture=__TEXTURE__;const $=id=>document.getElementById(id);let current=0,row=0,col=0,playing=false,loaded=null,generation=0,renderCount=0;const cache=new Map();document.body.classList.toggle('texture',texture);$('rowControl').hidden=texture;$('frameControl').hidden=texture;$('repeatControl').hidden=!texture;$('textureNote').hidden=!texture;
function image(url){return new Promise((ok,fail)=>{const im=new Image();im.onload=()=>ok(im);im.onerror=fail;im.src=url;});}
async function load(){const version=++generation,a=items[current];loaded=null;$('renderStatus').textContent='이미지 로드 중';if(!cache.has(current)){const [color,normal]=await Promise.all([image(a.colorUrl),image(a.normalUrl)]);cache.set(current,{color,normal});}if(version!==generation)return;loaded=cache.get(current);$('row').replaceChildren();for(let i=0;i<(a.rows||1);i++){const o=document.createElement('option');o.value=i;o.textContent=(i+1)+'행 · '+(a.rowOrder?.[i]||'정지');$('row').append(o);}$('prev').disabled=$('next').disabled=$('play').disabled=a.columns===1;draw();}
function draw(){if(!loaded)return;const a=items[current],w=texture?a.size[0]:a.cell[0],h=texture?a.size[1]:a.cell[1],sx=texture?0:col*w,sy=texture?0:row*h;const scratch=document.createElement('canvas');scratch.width=w;scratch.height=h;const c=scratch.getContext('2d',{willReadFrequently:true});c.drawImage(loaded.color,sx,sy,w,h,0,0,w,h);const rgba=c.getImageData(0,0,w,h);c.clearRect(0,0,w,h);c.drawImage(loaded.normal,sx,sy,w,h,0,0,w,h);const normal=c.getImageData(0,0,w,h),lit=c.createImageData(w,h);const az=Number($('azimuth').value)*Math.PI/180,el=Number($('elevation').value)*Math.PI/180;const light=[Math.cos(el)*Math.cos(az),Math.cos(el)*Math.sin(az),Math.sin(el)];const flat=$('flat').checked;
for(let p=0;p<w*h;p++){const i=p*4;let x=flat?0:normal.data[i]/255*2-1,y=flat?0:normal.data[i+1]/255*2-1,z=flat?1:normal.data[i+2]/255*2-1;const len=Math.hypot(x,y,z)||1;const diffuse=.32+.9*Math.max(0,(x*light[0]+y*light[1]+z*light[2])/len);for(let k=0;k<3;k++)lit.data[i+k]=Math.round(Math.min(1,Math.pow(rgba.data[i+k]/255,2.2)*diffuse)**(1/2.2)*255);lit.data[i+3]=rgba.data[i+3];}
const repeat=texture?Number($('repeat').value):1;for(const [id,pixels]of [['color',rgba],['normal',normal],['lit',lit]]){const canvas=$(id);canvas.width=w*repeat;canvas.height=h*repeat;const ctx=canvas.getContext('2d');ctx.imageSmoothingEnabled=false;for(let y=0;y<repeat;y++)for(let x=0;x<repeat;x++)ctx.putImageData(pixels,x*w,y*h);}
$('azValue').textContent=$('azimuth').value+'°';$('elValue').textContent=$('elevation').value+'°';$('litMode').textContent=flat?'평면 비교':'입체';$('frameLabel').textContent=a.label+(texture?' · '+repeat+'×'+repeat+' 반복':' · '+(row+1)+'행 / '+(col+1)+'칸');$('meta').textContent=texture?`${a.size[0]}×${a.size[1]}px / ${a.worldMeters[0]}×${a.worldMeters[1]}m / 32px·m⁻¹\n미러 반복 · 색/노멀 경계 일치 / OpenGL +Y / 검토용`:`전체 ${a.size[0]}×${a.size[1]} / ${a.columns}열×${a.rows}행 / 칸256×384\n발 기준128,352 · 색 그림 원본 유지 · 빈 영역 평면 노멀 / 검토용`;$('renderStatus').textContent='표시 완료 · 갱신 '+(++renderCount);}
$('asset').onchange=()=>{current=Number($('asset').value);row=col=0;playing=false;$('play').textContent='재생';load();};$('row').onchange=()=>{row=Number($('row').value);col=0;draw();};$('prev').onclick=()=>{col=(col+items[current].columns-1)%items[current].columns;draw();};$('next').onclick=()=>{col=(col+1)%items[current].columns;draw();};$('play').onclick=()=>{playing=!playing;$('play').textContent=playing?'일시정지':'재생';};for(const id of ['azimuth','elevation','flat','repeat'])$(id).oninput=draw;setInterval(()=>{if(playing&&loaded){col=(col+1)%items[current].columns;draw();}},125);load().catch(e=>{$('renderStatus').textContent='이미지를 불러오지 못했습니다.';console.error(e);});
</script></html>'''
 body=body.replace('__TITLE__',title).replace('__OPTIONS__',options).replace('__DATA__',json.dumps(payload,ensure_ascii=False)).replace('__TEXTURE__','true' if is_texture else 'false')
 (folder/'preview.html').write_text(body,encoding='utf-8');(ROOT/'_HTML'/filename).write_text(body,encoding='utf-8')
if __name__=='__main__':
 make(HERE,'codex_캐릭터노멀맵견본_v1.html')
 materials=HERE.parent/'codex_world_materials_v1'
 if (materials/'manifest.json').exists():make(materials,'codex_배경도트질감_노멀맵_v1.html',True)
 print('Built standalone lighting previews')
